class Extension(YAMLRoot):
    """
    A collection of recommended metadata terms (slots) developed by community experts, describing the specific context
    under which a sample was collected.
    """
    _inherited_slots: ClassVar[list[str]] = []

    class_class_uri: ClassVar[URIRef] = MIXS["Extension"]
    class_class_curie: ClassVar[str] = "MIXS:Extension"
    class_name: ClassVar[str] = "Extension"
    class_model_uri: ClassVar[URIRef] = MIXS.Extension


@dataclass(repr=False)
class Agriculture(Extension):
    """
    A collection of terms appropriate when sequencing samples obtained in an agricultural environment. Suitable to
    capture metadata appropriate to enhance crop productivity and agroecosystem health with the aim to facilitate
    research of agricultural microbiomes and their relationships to plant productivity and sustainable crop production
    from diverse crop management contexts.
    """
    _inherited_slots: ClassVar[list[str]] = []

